public static class Solution {
    public int missingNumber(int[] nums) {
        // Initialize 'res' with the length of the array 'nums'.
        // This accounts for the case when the missing number is 'n' itself.
        int res = nums.length;

        // Iterate through the array using a 'for' loop.
        for (int i = 0; i < nums.length; i++) {
            // In each iteration, add the difference between the index 'i'
            // and the value at that index 'nums[i]' to 'res'.
            // The idea is that if all numbers were present, the sum of (i - nums[i]) would be 0.
            // The missing number will cause a deviation from 0, allowing us to find it.
            res += i - nums[i];
        }

        // After the loop finishes, 'res' holds the value of the missing number.
        // This is because the sum of (i - nums[i]) for all present numbers cancels out,
        // leaving the missing number as the remaining value.
        return res;
    }
}

