public static class Solution {
    public int reverseBits(int n) {
        int res = 0; // Initialize the result variable to store the reversed bits

        // Loop through all 32 bits of the integer
        for (int i = 0; i < 32; i++) {
            // Extract the i-th bit from the input integer 'n'
            // Right shift 'n' by 'i' positions and then perform a bitwise AND with 1
            // This isolates the i-th bit (0 or 1)
            int bit = (n >> i) & 1;

            // Place the extracted bit at the reversed position in the result 'res'
            // Left shift the extracted 'bit' by (31 - i) positions
            // This moves the bit to its reversed position (e.g., bit 0 goes to bit 31)
            // Perform a bitwise OR with 'res' to set the bit at the correct position without affecting other bits
            res |= bit << (31 - i);
        }

        // Return the result, which now contains the reversed bits of the original integer
        return res;
    }
}

