public int climbStairs(int n) {
    // one: ways to reach the previous step
    // two: ways to reach two steps before
    int one = 1;
    int two = 1;

    // Loop n - 1 times
    for (int i = 0; i < n - 1; i++) {
        int temp = one;      // Store current value
        one = one + two;     // Sum of previous two
        two = temp;          // Shift forward
    }

    return one;
}

