public static class Solution {
    public int coinChange(int[] coins, int amount) {
        // dp[i] represents the minimum number of coins
        // required to make amount i
        int[] dp = new int[amount + 1];

        // Initialize all values as impossible (amount + 1)
        // We use amount + 1 as a value larger than any possible number of coins needed
        Arrays.fill(dp, amount + 1);

        // Base case:
        // 0 coins are needed to make amount 0
        dp[0] = 0;

        // Build the DP table from amount 1 to amount
        for (int a = 1; a <= amount; a++) {
            // Try each coin denomination
            for (int coin : coins) {
                // Check if the coin can be used
                if (a - coin >= 0) {
                    // Choose minimum coins between current min coins needed for amount 'a'
                    // and using this coin (1 + min coins needed for remaining amount a - coin)
                    dp[a] = Math.min(dp[a], 1 + dp[a - coin]);
                }
            }
        }

        // If amount is still impossible, return -1
        // dp[amount] will be greater than amount only if no combination of coins can reach the 'amount'
        return dp[amount] != amount + 1 ? dp[amount] : -1;
    }
}

