public static class Solution {
    /**
     * Given two strings text1 and text2, return the length of their longest common subsequence.
     * If there is no common subsequence, return 0.
     *
     * A subsequence of a string is a new string generated from the original string with some characters
     * (can be none) deleted without changing the relative order of the remaining characters.
     *
     * For example, "ace" is a subsequence of "abcde".
     * A common subsequence of two strings is a subsequence that is common to both strings.
     *
     * @param text1 The first string.
     * @param text2 The second string.
     * @return The length of their longest common subsequence.
     */
    public int longestCommonSubsequence(String text1, String text2) {
        // Get the lengths of the input strings.
        int m = text1.length();
        int n = text2.length();

        // Create a 2D DP table to store the lengths of LCS for different prefixes of the strings.
        // dp[i][j] will store the length of LCS of text1[0...i-1] and text2[0...j-1].
        int[][] dp = new int[m + 1][n + 1];

        // Iterate through the strings to populate the DP table.
        // Note that we start from index 1 to account for the empty string prefix.
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                // If the characters at the current positions in both strings match,
                // then the LCS length is incremented by 1, based on the LCS length of the previous prefixes.
                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                } else {
                    // If the characters do not match, then the LCS length is the maximum of the LCS lengths
                    // obtained by either excluding the current character from text1 or excluding the current character from text2.
                    dp[i][j] = Math.max(dp[i][j - 1], dp[i - 1][j]);
                }
            }
        }

        // The final result, i.e., the length of the LCS of text1 and text2, is stored in dp[m][n].
        return dp[m][n];
    }
}

