    public int rob(int[] nums) {
        // Edge case: if there is only one house,
        // the robber can only rob that house.
        if (nums.length == 1) return nums[0];

        /*
         In this problem (House Robber II), houses are arranged in a circle.
         This means:
         - First and last houses are neighbors
         - We cannot rob both of them

         So we split the problem into two linear cases:
         Case 1: Rob houses from index 0 to n-2 (skip the last house)
         Case 2: Rob houses from index 1 to n-1 (skip the first house)

         Then we take the maximum profit from these two cases.
        */

        int case1 = robLinear(nums, 0, nums.length - 2);
        int case2 = robLinear(nums, 1, nums.length - 1);

        // Return the maximum amount from both cases
        return Math.max(case1, case2);
    }

    private int robLinear(int[] nums, int start, int end) {
        /*
         This helper method solves the original House Robber I problem
         for a linear sequence of houses (not circular).

         rob1 -> max money robbed up to house i-2
         rob2 -> max money robbed up to house i-1
        */
        int rob1 = 0;
        int rob2 = 0;

        /*
         Iterate through the houses from start to end.
         At each house we have two choices:
         1. Rob this house -> rob1 + nums[i]
         2. Skip this house -> rob2

         We take the maximum of these two options.
        */
        for (int i = start; i <= end; i++) {

            // Decide whether to rob this house or skip it
            int temp = Math.max(rob1 + nums[i], rob2);

            // Shift values for next iteration
            // rob1 becomes previous rob2
            rob1 = rob2;

            // rob2 becomes the best value we just computed
            rob2 = temp;
        }

        // rob2 contains the maximum amount that can be robbed
        return rob2;
    }

}

