public static class Solution {
    /**
     * Depth-First Search (DFS) function to compute the number of decodings starting from index i.
     * Utilizes memoization to optimize the computation by storing previously computed results.
     *
     * @param i   The current index in the string s.
     * @param s   The input string to decode.
     * @param dp  A HashMap to store the computed results for memoization.
     * @return The number of possible decodings starting from index i.
     */
    public int dfs(int i, String s, Map<Integer, Integer> dp) {
        // If already computed, return memo value
        if (dp.containsKey(i)) {
            return dp.get(i);
        }

        // Base case: If we reach the end of the string, there is one way to decode (empty string).
        if (i == s.length()) {
            return 1;  // Represents a valid decoding (empty string)
        }

        // If current character is '0', invalid decoding because '0' itself cannot be decoded.
        if (s.charAt(i) == '0') {
            return 0;
        }

        // Recursive step: Decode using one digit.
        // Consider the substring starting from i+1.
        int res = dfs(i + 1, s, dp);

        // Recursive step: Decode using two digits if valid (10–26).
        // Check if we can form a valid two-digit number and if we're not at the end of the string.
        if (
            i + 1 < s.length() &&
            (s.charAt(i) == '1' ||
            (s.charAt(i) == '2' && s.charAt(i + 1) <= '6'))
        ) {
            // If the two-digit number is valid (between 10 and 26), add the number of decodings from i+2.
            res += dfs(i + 2, s, dp);
        }

        // Store result in memo
        dp.put(i, res);
        return res;
    }

    /**
     * Main function to calculate the number of ways to decode the input string s.
     *
     * @param s The input string to decode.
     * @return The total number of ways to decode the string.
     */
    public int numDecodings(String s) {
        // Initialize a HashMap to store the intermediate results for memoization.
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(s.length(), 1); // Base case: An empty string has one way to decode.

        // Start the DFS from the beginning of the string (index 0).
        return dfs(0, s, dp);
    }
}

