    function dfs(i: number): number {
        // If result already computed, return it from the memo
        if (dp.has(i)) return dp.get(i)!;

        // If current character is '0', no valid decoding is possible from this point
        if (s[i] === '0') return 0;

        // Take one digit: Consider the current digit as a single-digit decoding.
        // The number of ways to decode the rest of the string starting from the next index (i + 1) is added to the result.
        let res = dfs(i + 1);

        // Take two digits if they form a valid letter (10–26).
        // Check if taking two digits (s[i] and s[i + 1]) forms a number between 10 and 26 (inclusive).
        // s[i] === '1' means it can be 10-19
        // s[i] === '2' means it can be 20-26, need to check s[i+1] <= 6
        if (
            i + 1 < s.length &&
            (s[i] === '1' || (s[i] === '2' && '0123456'.includes(s[i + 1])))
        ) {
            // If the two digits form a valid number, add the number of ways to decode
            // the rest of the string starting from index i + 2 to the result.
            res += dfs(i + 2);
        }

        // Store result in memo to avoid recomputation
        dp.set(i, res);
        return res;
    }

    // Start decoding from index 0
    return dfs(0);
}

